\set ON_ERROR_STOP on
begin;
create function pg_temp.invite_assert(ok boolean,message text)returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL %',message;end if;raise notice 'PASS %',message;end $$;
create function pg_temp.invite_input(email text,token text,request_id uuid default extensions.gen_random_uuid())returns jsonb language sql as $$select jsonb_build_object('id',extensions.gen_random_uuid(),'email',email,'requestId',request_id,'tokenHash',encode(extensions.digest(token||email,'sha256'),'hex'),'tokenEncrypted','v1.'||repeat('a',16)||'.'||repeat('b',22)||'.'||repeat('c',86),'origin','https://dev.kyaa.io','locale','ko')$$;
do $$declare owner uuid:=gen_random_uuid();manager uuid:=gen_random_uuid();recipient uuid:=gen_random_uuid();outsider uuid:=gen_random_uuid();page uuid:=gen_random_uuid();other_page uuid:=gen_random_uuid();input jsonb;receipt jsonb;preview jsonb;decision jsonb;invite uuid;job jsonb;request_id uuid:=gen_random_uuid();users_before bigint;count_before bigint;bad boolean;other_invite uuid;begin
 insert into public.app_users(id,privy_user_id,verified_email)values(owner,'did:privy:invite-'||owner,owner||'@example.test'),(manager,'did:privy:invite-'||manager,manager||'@example.test'),(recipient,'did:privy:invite-'||recipient,recipient||'@example.test'),(outsider,'did:privy:invite-'||outsider,outsider||'@example.test');
 insert into public.group_pages(id,kind,name)values(page,'hobby','Invite fixture'),(other_page,'hobby','Other fixture');insert into public.group_memberships(page_id,app_user_id,role)values(page,owner,'owner'),(page,manager,'manager'),(other_page,outsider,'owner');
 users_before:=(select count(*)from public.app_users);
 input:=pg_temp.invite_input(recipient||'@example.test',repeat('a',64),request_id);
 receipt:=public.group_membership_invitation_dispatch('create',owner,page,null,input);invite:=(receipt->>'id')::uuid;
 perform pg_temp.invite_assert(receipt->>'status'='pending'and receipt->>'deliveryStatus'='pending'and not(receipt?'email'or receipt?'token'or receipt?'tokenEncrypted'),'create only queues a private invitation');
 perform pg_temp.invite_assert(not exists(select 1 from public.group_memberships where page_id=page and app_user_id=recipient)and(select count(*)from public.app_users)=users_before,'email invitation creates no membership or fake account');
 perform pg_temp.invite_assert(public.group_membership_invitation_dispatch('create',owner,page,null,input||jsonb_build_object('id',gen_random_uuid(),'tokenHash',repeat('d',64)))=receipt and(select count(*)from public.group_invitation_email_outbox where invitation_id=invite)=1,'replay ignores randomized token material and never requeues');
 begin perform public.group_membership_invitation_dispatch('create',owner,page,null,input||jsonb_build_object('email','changed@example.test'));raise exception 'changed request accepted';exception when raise_exception then if sqlerrm<>'GROUP_INVITATION_CONFLICT'then raise;end if;end;
 begin perform public.group_membership_invitation_dispatch('create',recipient,page,null,pg_temp.invite_input('x@example.test',repeat('e',64)));raise exception 'memberless invite allowed';exception when raise_exception then if sqlerrm<>'GROUP_INVITATION_FORBIDDEN'then raise;end if;end;
 begin perform public.group_membership_invitation_dispatch('create',manager,page,null,pg_temp.invite_input('x@example.test',repeat('e',64))||'{"role":"owner"}');raise exception 'role escalation allowed';exception when raise_exception then if sqlerrm<>'GROUP_INVITATION_INVALID'then raise;end if;end;
 preview:=public.group_membership_invitation_dispatch('preview',null,null,invite,jsonb_build_object('tokenHash',input->>'tokenHash'));
 perform pg_temp.invite_assert(preview->>'loginRequired'='true'and not(preview?'email')and(select state from public.group_membership_invitations where id=invite)='pending'and not exists(select 1 from public.group_membership_invitation_consents where invitation_id=invite),'anonymous preview/scanner GET never consumes or registers');
 begin perform public.group_membership_invitation_dispatch('preview',outsider,null,invite,jsonb_build_object('tokenHash',input->>'tokenHash'));raise exception 'wrong verified email allowed';exception when raise_exception then if sqlerrm<>'GROUP_INVITATION_NOT_FOUND'then raise;end if;end;
 preview:=public.group_membership_invitation_dispatch('preview',recipient,null,invite,jsonb_build_object('tokenHash',input->>'tokenHash'));
 decision:=jsonb_build_object('tokenHash',input->>'tokenHash','requestId',gen_random_uuid(),'membershipConsent',true,'privacyConsent',true,'membershipVersion',preview->>'membershipVersion','privacyVersion',preview->>'privacyVersion','answer','');
 begin perform public.group_membership_invitation_dispatch('accept',recipient,null,invite,decision||'{"privacyConsent":false}');raise exception 'missing consent accepted';exception when raise_exception then if sqlerrm<>'GROUP_INVITATION_CONSENT_REQUIRED'then raise;end if;end;
 begin perform public.group_membership_invitation_dispatch('accept',recipient,null,invite,decision||'{"privacyVersion":"old"}');raise exception 'old privacy version accepted';exception when raise_exception then if sqlerrm<>'GROUP_INVITATION_CONSENT_REQUIRED'then raise;end if;end;
 job:=public.claim_group_invitation_email('dev');perform pg_temp.invite_assert(job->>'invitationId'=invite::text and not(job?'token'),'worker leases only encrypted token material');
 perform pg_temp.invite_assert(public.begin_group_invitation_email_send((job->>'id')::uuid,(job->>'attemptToken')::uuid)and not public.begin_group_invitation_email_send((job->>'id')::uuid,(job->>'attemptToken')::uuid),'durable begin can happen only once for claim');
 perform public.finish_group_invitation_email_send((job->>'id')::uuid,(job->>'attemptToken')::uuid,'throttled');
 perform pg_temp.invite_assert((select status='pending'and token_encrypted is not null from public.group_invitation_email_outbox where invitation_id=invite),'explicit throttling keeps encrypted material for bounded retry');
 update public.group_invitation_email_outbox set available_at=now()-interval'1 minute'where invitation_id=invite;job:=public.claim_group_invitation_email('dev');perform public.begin_group_invitation_email_send((job->>'id')::uuid,(job->>'attemptToken')::uuid);perform public.finish_group_invitation_email_send((job->>'id')::uuid,(job->>'attemptToken')::uuid,'unknown');
 perform pg_temp.invite_assert((select status='delivery_unknown'and token_encrypted is null from public.group_invitation_email_outbox where invitation_id=invite)and public.claim_group_invitation_email('dev')is null,'unknown delivery is never leased or resent');
 update public.group_pages set question='Why join?'where id=page;
 begin perform public.group_membership_invitation_dispatch('accept',recipient,null,invite,decision);raise exception 'required join answer bypassed';exception when raise_exception then if sqlerrm<>'GROUPS_INVALID_REQUEST'then raise;end if;end;
 decision:=decision||'{"answer":"Synthetic answer"}';
 receipt:=public.group_membership_invitation_dispatch('accept',recipient,null,invite,decision);
 perform pg_temp.invite_assert(receipt->>'status'='accepted'and(select role from public.group_memberships where page_id=page and app_user_id=recipient)='member'and(select count(*)from public.group_membership_invitation_consents where invitation_id=invite)=1,'verified recipient explicit consent registers exactly one member');
 perform pg_temp.invite_assert(public.group_membership_invitation_dispatch('accept',recipient,null,invite,decision)=receipt and(select count(*)from public.group_membership_invitation_consents where invitation_id=invite)=1,'accept replay preserves one consent and membership');
 begin perform public.group_membership_invitation_dispatch('accept',recipient,null,invite,decision||'{"privacyVersion":"changed"}');raise exception 'changed decision replay allowed';exception when raise_exception then if sqlerrm<>'GROUP_INVITATION_CONFLICT'then raise;end if;end;
 begin update public.group_membership_invitation_consents set privacy_version='changed'where invitation_id=invite;raise exception 'consent mutation allowed';exception when raise_exception then if sqlerrm<>'GROUP_INVITATION_CONSENT_IMMUTABLE'then raise;end if;end;
 input:=pg_temp.invite_input(outsider||'@example.test',repeat('b',64));other_invite:=(public.group_membership_invitation_dispatch('create',manager,page,null,input)->>'id')::uuid;
 perform public.group_membership_invitation_dispatch('decline',outsider,null,other_invite,jsonb_build_object('tokenHash',input->>'tokenHash','requestId',gen_random_uuid()));
 perform pg_temp.invite_assert(not exists(select 1 from public.group_memberships where page_id=page and app_user_id=outsider)and(select state from public.group_membership_invitations where id=other_invite)='declined','manager can invite; recipient decline never creates membership');
 input:=pg_temp.invite_input('unregistered@example.test',repeat('c',64));other_invite:=(public.group_membership_invitation_dispatch('create',owner,page,null,input)->>'id')::uuid;
 perform pg_temp.invite_assert((select count(*)from public.app_users)=users_before,'unregistered destination never creates app_user or notification channel');
 begin perform public.group_membership_invitation_dispatch('create',owner,page,null,pg_temp.invite_input('unregistered@example.test',repeat('d',64)));raise exception 'cooldown bypass';exception when raise_exception then if sqlerrm<>'GROUP_INVITATION_RATE_LIMITED'then raise;end if;end;
 update public.group_membership_invitations set expires_at=clock_timestamp()-interval'1 second'where id=other_invite;
 begin perform public.group_membership_invitation_dispatch('preview',null,null,other_invite,jsonb_build_object('tokenHash',input->>'tokenHash'));raise exception 'expired preview allowed';exception when raise_exception then if sqlerrm<>'GROUP_INVITATION_NOT_FOUND'then raise;end if;end;
 perform pg_temp.invite_assert((select state from public.group_membership_invitations where id=other_invite)='pending','expired preview is read-only');perform public.maintain_group_invitation_email();
 perform pg_temp.invite_assert((select state from public.group_membership_invitations where id=other_invite)='expired'and(select token_encrypted is null from public.group_invitation_email_outbox where invitation_id=other_invite),'maintenance expires invitation and erases mail secret');
 update public.group_pages set question=null where id=page;
 input:=pg_temp.invite_input(owner||'@example.test',repeat('f',64));other_invite:=(public.group_membership_invitation_dispatch('create',manager,page,null,input)->>'id')::uuid;preview:=public.group_membership_invitation_dispatch('preview',owner,null,other_invite,jsonb_build_object('tokenHash',input->>'tokenHash'));
 perform public.group_membership_invitation_dispatch('accept',owner,null,other_invite,jsonb_build_object('tokenHash',input->>'tokenHash','requestId',gen_random_uuid(),'membershipConsent',true,'privacyConsent',true,'membershipVersion',preview->>'membershipVersion','privacyVersion',preview->>'privacyVersion'));
 perform pg_temp.invite_assert((select role from public.group_memberships where page_id=page and app_user_id=owner)='owner','existing owner consumes invite without demotion or member duplication');
 perform pg_temp.invite_assert(not has_table_privilege('service_role','public.group_membership_invitations','SELECT')and not has_function_privilege('authenticated','public.group_membership_invitation_dispatch(text,uuid,uuid,uuid,jsonb)','EXECUTE'),'private invitations and RPC deny direct browser access');
end $$;
rollback;
